mapper.select:
SELECT COUNT(*)
FROM   PURCHASE_ORDER P 
       LEFT JOIN CLIENT C ON P.CLIENT_NO = C.CLIENT_NO AND C.DEL_STATUS = 0
       LEFT JOIN EMP E ON P.EMP_NO = E.EMP_NO AND E.DEL_STATUS = 0

	   P.DEL_STATUS = 0

	   AND C.CLIENT_NAME LIKE '%' || #{client_Name} || '%'


	   AND E.EMP_NAME LIKE '%' || #{empName} || '%'


	   AND P.IN_STATUS = #{in_Status}


	   AND P.PURCHASE_DATE >=#{purchase_Date_Start}


	   AND P.PURCHASE_DATE <=#{purchase_Date_End}

SELECT P.PURCHASE_NO, P.PURCHASE_DATE, P.IN_STATUS, P.DEL_STATUS, P.PURCHASE_TITLE , P.COMPLETE_DATE, P.IN_DATE , H.CLIENT_NO, H.CLIENT_NAME, E.EMP_NO, E.EMP_NAME , I.PARTS_NO, I.PURCHASE_ITEM_CNT, I.PURCHASE_ITEM_INCNT , I.PURCHASE_ITEM_COST, PA.PARTS_NAME FROM (SELECT ROWNUM RN, A.* FROM (SELECT * FROM PURCHASE_ORDER WHERE DEL_STATUS = 0 ORDER BY PURCHASE_NO DESC ) A )P LEFT JOIN CLIENT_HIS H ON P.CLIENT_NO = H.CLIENT_NO AND COALESCE(P.MODIFY_DATE, P.IN_DATE) BETWEEN H.START_DATE AND H.END_DATE LEFT JOIN EMP E ON P.EMP_NO = E.EMP_NO LEFT JOIN PURCHASE_ITEM I ON P.PURCHASE_NO = I.PURCHASE_NO LEFT JOIN PARTS PA ON I.PARTS_NO = PA.PARTS_NO
AND H.CLIENT_NAME LIKE '%' || #{client_Name} || '%'
AND E.EMP_NAME LIKE '%' || #{empName} || '%'
AND P.IN_STATUS = #{in_Status}
AND P.PURCHASE_DATE >=#{purchase_Date_Start}
AND P.PURCHASE_DATE <=#{purchase_Date_End}
AND RN >=#{start} AND RN <=#{end}
ORDER BY P.PURCHASE_NO DESC

mapper.insert:
INSERT INTO PURCHASE_ITEM (PURCHASE_NO, PARTS_NO, PURCHASE_ITEM_CNT, PURCHASE_ITEM_INCNT, PURCHASE_ITEM_COST)

SELECT #{purchase_No}, #{item.partsDTO.parts_no}, #{item.purchase_Item_Cnt}, 0, #{item.purchase_Item_Cost}
FROM   DUAL

mapper.delete:
BEGIN

DELETE FROM PURCHASE_ITEM WHERE PURCHASE_NO = #{item.purchase_No} AND PARTS_NO = #{item.parts_no};

END;

mapper.select:
SELECT IN_STATUS
FROM   PURCHASE_ORDER
WHERE  PURCHASE_NO = #{value}

SELECT PARTS_NO
FROM   PURCHASE_ITEM
WHERE  PURCHASE_NO = #{value}

mapper.update:
UPDATE PURCHASE_ORDER
SET    IN_STATUS = #{in_Status}
WHERE  PURCHASE_NO = #{purchase_No}

BEGIN

UPDATE PURCHASE_ITEM
SET    PURCHASE_ITEM_INCNT = PURCHASE_ITEM_CNT
WHERE  PURCHASE_NO 	= #{purchase_No} AND
       PARTS_NO 	= #{item};

END;

BEGIN

UPDATE PURCHASE_ITEM
SET    PURCHASE_ITEM_INCNT = 0
WHERE  PURCHASE_NO = #{item.purchase_No}
AND    PARTS_NO = #{item.parts_no};

END;

UPDATE PURCHASE_ORDER
SET	   DEL_STATUS = 1
WHERE  PURCHASE_NO = #{value}
